  "error.passwords_mismatch": { en:"Passwords do not match.", hi:"पासवर्ड मेल नहीं खाते।", bn:"পাসওয়ার্ড মিলছে না।", te:"పాస్‌వర్డ్‌లు సరిపోలడం లేదు.", mr:"पासवर्ड जुळत नाहीत.", ta:"கடவுச்சொற்கள் பொருந்தவில்லை.", gu:"પાસવર્ડ મેળ ખાતા નથી.", kn:"ಪಾಸ್‌ವರ್ಡ್‌ಗಳು ಹೊಂದಿಕೆಯಾಗುತ್ತಿಲ್ಲ.", pa:"ਪਾਸਵਰਡ ਮੇਲ ਨਹੀਂ ਖਾਂਦੇ.", or:"ପାସୱାର୍ଡ ମେଳ ଖାଉନାହିଁ.", ml:"പാസ്‌വേഡുകൾ പൊരുത്തപ്പെടുന്നില്ല." },
  "error.password_length": { en:"Password must be at least 6 characters.", hi:"पासवर्ड कम से कम 6 अक्षर का होना चाहिए।", bn:"পাসওয়ার্ড কমপক্ষে ৬ অক্ষরের হতে হবে।", te:"పాస్‌వర్డ్ కనీసం 6 అక్షరాలు ఉండాలి.", mr:"पासवर्ड किमान 6 वर्णांचा असावा.", ta:"கடவுச்சொல் குறைந்தது 6 எழுத்துக்களாக இருக்க வேண்டும்.", gu:"પાસવર્ડ ઓછામાં ઓછો 6 અક્ષરોનો હોવો જોઈએ.", kn:"ಪಾಸ್‌ವರ್ಡ್ ಕನಿಷ್ಠ 6 ಅಕ್ಷರಗಳಾಗಿರಬೇಕು.", pa:"ਪਾਸਵਰਡ ਘੱਟੋ-ਘੱਟ 6 ਅੱਖਰਾਂ ਦਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ.", or:"ପାସୱାର୍ଡ ଅତିକମରେ 6 ଅକ୍ଷର ହେବା ଆବଶ୍ୟକ.", ml:"പാസ്‌വേഡ് കുറഞ്ഞത് 6 അക്ഷരങ്ങൾ ആയിരിക്കണം." },
  "error.fill_all_fields": { en:"Please fill in all fields.", hi:"कृपया सभी फ़ील्ड भरें।", bn:"সব ক্ষেত্র পূরণ করুন।", te:"దయచేసి అన్ని ఫీల్డ్‌లను పూరించండి.", mr:"कृपया सर्व फील्ड भरा.", ta:"அனைத்து புலங்களையும் நிரப்பவும்.", gu:"કૃપા કરીને બધા ક્ષેત્રો ભરો.", kn:"ದಯವಿಟ್ಟು ಎಲ್ಲಾ ಕ್ಷೇತ್ರಗಳನ್ನು ಭರ್ತಿ ಮಾಡಿ.", pa:"ਕਿਰਪਾ ਕਰਕੇ ਸਾਰੇ ਖੇਤਰ ਭਰੋ.", or:"ଦୟାକରି ସମସ୍ତ ଫିଲ୍ଡ ପୂରଣ କରନ୍ତୁ.", ml:"എല്ലാ ഫീൽഡുകളും പൂരിപ്പിക്കുക." },
  "error.google_coming_soon": { en:"Google sign-in coming soon!", hi:"Google साइन-इन जल्द आ रहा है!", bn:"Google সাইন-ইন শীঘ্রই আসছে!", te:"Google సైన్-ఇన్ త్వరలో వస్తుంది!", mr:"Google साइन-इन लवकरच येत आहे!", ta:"Google உள்நுழைவு விரைவில் வருகிறது!", gu:"Google સાઇન-ઇન ટૂંક સમયમાં આવી રહ્યું છે!", kn:"Google ಸೈನ್-ಇನ್ ಶೀಘ್ರದಲ್ಲೇ ಬರುತ್ತಿದೆ!", pa:"Google ਸਾਈਨ-ਇਨ ਜਲਦੀ ਆ ਰਿਹਾ ਹੈ!", or:"Google ସାଇନ-ଇନ ଶୀଘ୍ର ଆସୁଛି!", ml:"Google സൈൻ-ഇൻ ഉടൻ വരുന്നു!" },
  "error.analysis_failed": { en:"Analysis failed. Please try again.", hi:"विश्लेषण विफल रहा। कृपया पुनः प्रयास करें।", bn:"বিশ্লেষণ ব্যর্থ হয়েছে। আবার চেষ্টা করুন।", te:"విశ్లేషణ విఫలమైంది. దయచేసి మళ్లీ ప్రయత్నించండి.", mr:"विश्लेषण अयशस्वी झाले. कृपया पुन्हा प्रयत्न करा.", ta:"பகுப்பாய்வு தோல்வியடைந்தது. மீண்டும் முயற்சிக்கவும்.", gu:"વિશ્લેષણ નિષ્ફળ થયું. કૃપા કરીને ફરી પ્રયાસ કરો.", kn:"ವಿಶ್ಲೇಷಣೆ ವಿಫಲವಾಗಿದೆ. ದಯವಿಟ್ಟು ಮತ್ತೆ ಪ್ರಯತ್ನಿಸಿ.", pa:"ਵਿਸ਼ਲੇਸ਼ਣ ਅਸਫਲ ਰਿਹਾ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।", or:"ବିଶ୍ଲେଷଣ ବିଫଳ ହୋଇଛି। ଦୟାକରି ପୁଣି ଚେଷ୍ଟା କରନ୍ତୁ।", ml:"വിശകലനം പരാജയപ്പെട്ടു. വീണ്ടും ശ്രമിക്കുക." },
  "error.image_process_failed": { en:"Failed to process images. Please try with smaller images or fewer images at once.", hi:"छवियों को संसाधित करने में विफल। कृपया छोटी छवियों या एक बार में कम छवियों के साथ प्रयास करें।", bn:"ছবি প্রক্রিয়া করতে ব্যর্থ। ছোট ছবি বা একবারে কম ছবি দিয়ে চেষ্টা করুন।", te:"చిత్రాలను ప్రాసెస్ చేయడంలో విఫలమైంది. చిన్న చిత్రాలు లేదా ఒకేసారి తక్కువ చిత్రాలతో ప్రయత్నించండి.", mr:"प्रतिमा प्रक्रिया करण्यात अयशस्वी. कृपया लहान प्रतिमा किंवा एकाच वेळी कमी प्रतिमांसह प्रयत्न करा.", ta:"படங்களைச் செயலாக்க முடியவில்லை. சிறிய படங்கள் அல்லது ஒரே நேரத்தில் குறைவான படங்களுடன் முயற்சிக்கவும்.", gu:"છબીઓ પ્રક્રિયા કરવામાં નિષ્ફળ. કૃપા કરીને નાની છબીઓ અથવા એક સમયે ઓછી છબીઓ સાથે પ્રયાસ કરો.", kn:"ಚಿತ್ರಗಳನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸಲು ವಿಫಲವಾಗಿದೆ. ದಯವಿಟ್ಟು ಚಿಕ್ಕ ಚಿತ್ರಗಳು ಅಥವಾ ಒಂದೇ ಬಾರಿಗೆ ಕಡಿಮೆ ಚಿತ್ರಗಳೊಂದಿಗೆ ಪ್ರಯತ್ನಿಸಿ.", pa:"ਤਸਵੀਰਾਂ ਨੂੰ ਪ੍ਰਕਿਰਿਆ ਕਰਨ ਵਿੱਚ ਅਸਫਲ। ਕਿਰਪਾ ਕਰਕੇ ਛੋਟੀਆਂ ਤਸਵੀਰਾਂ ਜਾਂ ਇੱਕ ਵਾਰ ਵਿੱਚ ਘੱਟ ਤਸਵੀਰਾਂ ਨਾਲ ਕੋਸ਼ਿਸ਼ ਕਰੋ।", or:"ଚିତ୍ର ପ୍ରକ୍ରିୟାକରଣ ବିଫଳ ହୋଇଛି। ଦୟାକରି ଛୋଟ ଚିତ୍ର କିମ୍ବା ଏକ ସମୟରେ କମ ଚିତ୍ର ସହିତ ଚେଷ୍ଟା କରନ୍ତୁ।", ml:"ചിത്രങ്ങൾ പ്രോസസ്സ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു. ചെറിയ ചിത്രങ്ങൾ അല്ലെങ്കിൽ ഒരേസമയം കുറച്ച് ചിത്രങ്ങൾ ഉപയോഗിച്ച് ശ്രമിക്കുക." },

