  "result.healthy_area": { en:"Blue/Cyan = Healthy Area", hi:"नीला/सियान = स्वस्थ क्षेत्र", bn:"নীল/সায়ান = সুস্থ এলাকা", te:"నీలం/సియాన్ = ఆరోగ్యకరమైన ప్రాంతం", mr:"निळा/सियान = निरोगी क्षेत्र", ta:"நீலம்/சியான் = ஆரோக்கியமான பகுதி", gu:"વાદળી/સાયન = સ્વસ્થ વિસ્તાર", kn:"ನೀಲಿ/ಸಯಾನ್ = ಆರೋಗ್ಯಕರ ಪ್ರದೇಶ", pa:"ਨੀਲਾ/ਸਿਆਨ = ਸਿਹਤਮੰਦ ਖੇਤਰ", or:"ନୀଳ/ସିଆନ = ସୁସ୍ଥ ଅଞ୍ଚଳ", ml:"നീല/സയാൻ = ആരോഗ്യകരമായ പ്രദേശം" },
  "result.mild_infection": { en:"Green/Yellow = Mild Infection", hi:"हरा/पीला = हल्का संक्रमण", bn:"সবুজ/হলুদ = হালকা সংক্রমণ", te:"ఆకుపచ్చ/పసుపు = తేలికపాటి సంక్రమణ", mr:"हिरवा/पिवळा = सौम्य संसर्ग", ta:"பச்சை/மஞ்சள் = லேசான தொற்று", gu:"લીલો/પીળો = હળવો ચેપ", kn:"ಹಸಿರು/ಹಳದಿ = ಸೌಮ್ಯ ಸೋಂಕು", pa:"ਹਰਾ/ਪੀਲਾ = ਹਲਕਾ ਸੰਕਰਮਣ", or:"ସବୁଜ/ହଳଦିଆ = ସାମାନ୍ୟ ସଂକ୍ରମଣ", ml:"പച്ച/മഞ്ഞ = നേരിയ അണുബാധ" },
  "result.severe_infection": { en:"Orange/Red = Severe Infection", hi:"नारंगी/लाल = गंभीर संक्रमण", bn:"কমলা/লাল = গুরুতর সংক্রমণ", te:"నారింజ/ఎరుపు = తీవ్రమైన సంక్రమణ", mr:"नारिंगी/लाल = गंभीर संसर्ग", ta:"ஆரஞ்சு/சிவப்பு = கடுமையான தொற்று", gu:"નારંગી/લાલ = ગંભીર ચેપ", kn:"ಕಿತ್ತಳೆ/ಕೆಂಪು = ತೀವ್ರ ಸೋಂಕು", pa:"ਸੰਤਰੀ/ਲਾਲ = ਗੰਭੀਰ ਸੰਕਰਮਣ", or:"କମଳା/ଲାଲ = ଗୁରୁତର ସଂକ୍ରମଣ", ml:"ഓറഞ്ച്/ചുവപ്പ് = ഗുരുതരമായ അണുബാധ" },
  "result.warmer_colors": { en:"Warmer colors indicate higher disease severity", hi:"गर्म रंग उच्च रोग गंभीरता का संकेत देते हैं", bn:"উষ্ণ রং উচ্চতর রোগের তীব্রতা নির্দেশ করে", te:"వెచ్చని రంగులు అధిక వ్యాధి తీవ్రతను సూచిస్తాయి", mr:"उबदार रंग रोगाची उच्च तीव्रता दर्शवतात", ta:"வெப்பமான வண்ணங்கள் அதிக நோய் தீவிரத்தை குறிக்கின்றன", gu:"ગરમ રંગો ઉચ્ચ રોગની તીવ્રતા સૂચવે છે", kn:"ಬೆಚ್ಚಗಿನ ಬಣ್ಣಗಳು ಹೆಚ್ಚಿನ ರೋಗದ ತೀವ್ರತೆಯನ್ನು ಸೂಚಿಸುತ್ತವೆ", pa:"ਗਰਮ ਰੰਗ ਉੱਚ ਬਿਮਾਰੀ ਦੀ ਗੰਭੀਰਤਾ ਨੂੰ ਦਰਸਾਉਂਦੇ ਹਨ", or:"ଉଷ୍ମ ରଙ୍ଗ ଅଧିକ ରୋଗର ଗୁରୁତ୍ୱକୁ ସୂଚିତ କରେ", ml:"ചൂടുള്ള നിറങ്ങൾ ഉയർന്ന രോഗ തീവ്രതയെ സൂചിപ്പിക്കുന്നു" },
  "result.analyzing": { en:"Analyzing your crop image", hi:"आपकी फसल की छवि का विश्लेषण किया जा रहा है", bn:"আপনার ফসলের ছবি বিশ্লেষণ করা হচ্ছে", te:"మీ పంట చిత్రాన్ని విశ్లేషిస్తోంది", mr:"तुमच्या पिकाच्या प्रतिमेचे विश्लेषण करत आहे", ta:"உங்கள் பயிர் படத்தை பகுப்பாய்வு செய்கிறது", gu:"તમારી પાક છબીનું વિશ્લેષણ કરી રહ્યું છે", kn:"ನಿಮ್ಮ ಬೆಳೆ ಚಿತ್ರವನ್ನು ವಿಶ್ಲೇಷಿಸಲಾಗುತ್ತಿದೆ", pa:"ਤੁਹਾਡੀ ਫਸਲ ਦੀ ਤਸਵੀਰ ਦਾ ਵਿਸ਼ਲੇਸ਼ਣ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ", or:"ଆପଣଙ୍କ ଫସଲ ଚିତ୍ର ବିଶ୍ଲେଷଣ କରାଯାଉଛି", ml:"നിങ്ങളുടെ വിള ചിത്രം വിശകലനം ചെയ്യുന്നു" },
  "result.analyzing_plural": { en:"s", hi:"ों", bn:"গুলি", te:"లు", mr:"ं", ta:"கள்", gu:"ઓ", kn:"ಗಳು", pa:"ਾਂ", or:"ଗୁଡିକ", ml:"കൾ" },
