  // --- Weather-Aware Disease Risk (Phase 7) ---
  "weather.title": { en:"Weather-Aware Disease Risk", hi:"मौसम-आधारित रोग जोखिम", bn:"আবহাওয়াভিত্তিক রোগ ঝুঁকি", te:"వాతావరణ-ఆధారిత వ్యాధి రిస్క్", mr:"हवामान-आधारित रोग धोका", ta:"வானிலை சார்ந்த நோய் ஆபத்து", gu:"હવામાન-આધારિત રોગ જોખમ", kn:"ಹವಾಮಾನ-ಆಧಾರಿತ ರೋಗ ಅಪಾಯ", pa:"ਮੌਸਮ-ਅਧਾਰਿਤ ਬਿਮਾਰੀ ਜੋਖਮ", or:"ମୌସମ-ଆଧାରିତ ରୋଗ ବିପଦ", ml:"കാലാവസ്ഥ അടിസ്ഥാനമാക്കിയുള്ള രോഗ അപക്ടം" },
  "weather.no_coords": { en:"Add field coordinates to see weather risk.", hi:"मौसम जोखिम देखने के लिए खेत के निर्देशांक जोड़ें।", bn:"আবহাওয়া ঝুঁকি দেখতে ক্ষেত্রের স্থানাঙ্ক যোগ করুন।", te:"వాతావరణ రిస్క్ చూడడానికి ఫీల్డ్ కోఆర్డినేట్‌లను జోడించండి.", mr:"हवामान धोका पाहण्यासाठी शेत समन्वय जोडा.", ta:"வானிலை ஆபத்தைக் காண புலளவு ளூல்களைச் சேர்க்கவும்.", gu:"હવામાન જોખમ જોવા માટે ક્ષેત્ર નિર્દેશાંકો ઉમેરો.", kn:"ಹವಾಮಾನ ಅಪಾಯ ನೋಡಲು ಕ್ಷೇತ್ರದ ನಿರ್ದೇಶಾಂಕಗಳನ್ನು ಸೇರಿಸಿ.", pa:"ਮੌਸਮ ਜੋਖਮ ਵੇਖਣ ਲਈ ਖੇਤ ਧੁਰੇ ਸ਼ਾਮਲ ਕਰੋ।", or:"ମୌସମ ବିପଦ ଦେଖିବା ପାଇଁ କ୍ଷେତ୍ର ସ୍ଥାନାଙ୍କ ଯୋଡନ୍ତୁ।", ml:"കാലാവസ്ഥ അപക്ടം കാണാൻ ഫീൽഡ് കോർഡിനേറ്റുകൾ ചേർക്കുക." },
  "weather.error": { en:"Weather data temporarily unavailable.", hi:"मौसम डेटा अस्थायी रूप से उपलब्ध नहीं।", bn:"আবহাওয়া তথ্য সাময়িকভাবে পাওয়া যাচ্ছে না।", te:"వాతావరణ డేటా తాత్కాలికంగా అందుబాటులో లేదు.", mr:"हवामान डेटा तात्पुरता उपलब्ध नाही.", ta:"வானிலை தரவு தற்காலிகமாக கிடைக்கவில்லை.", gu:"હવામાન ડેટા અસ્થાયી રૂપે ઉપલબ્ધ નથી.", kn:"ಹವಾಮಾನ ಡೇಟಾ ತಾತ್ಕಾಲಿಕವಾಗಿ ಲಭ್ಯವಿಲ್ಲ.", pa:"ਮੌਸਮ ਡਾਟਾ ਆਰਜ਼ੀ ਤੌਰ 'ਤੇ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।", or:"ମୌସମ ତଥ୍ୟ ଅସ୍ଥାୟୀ ଭାବରେ ଉପଲବ୍ଧ ନୁହେଁ।", ml:"കാലാവസ്ഥ ഡാറ്റ താൽക്കാലികമായി ലഭ്യമല്ല." },
  "weather.no_rule": { en:"No weather rule for this disease.", hi:"इस रोग के लिए कोई मौसम नियम नहीं।", bn:"এই রোগের জন্য কোনো আবহাওয়া নিয়ম নেই।", te:"ఈ వ్యాధికి వాతావరణ నియమం లేదు.", mr:"या रोगासाठी हवामान नियम नाही.", ta:"இந்த நோயுக்கு வானிலை விதி இல்லை.", gu:"આ રોગ માટે કોઈ હવામાન નિયમ નથી.", kn:"ಈ ರೋಗಕ್ಕೆ ಹವಾಮಾನ ನಿಯಮವಿಲ್ಲ.", pa:"ਇਸ ਬਿਮਾਰੀ ਲਈ ਕੋਈ ਮੌਸਮ ਨਿਯਮ ਨਹੀਂ ਹੈ।", or:"ଏହି ରୋଗ ପାଇଁ କୌଣସି ମୌସମ ନିୟମ ନାହିଁ।", ml:"ഈ രോഗത്തിന് കാലാവസ്ഥ നിയമമില്ല." },
